/* Collection comes from the retrieval backend via window.MSF_DOCUMENTS
 * (generated by `msf-retrieval export`, see documents.js). Falls back to empty.
 *
 * Behaviour:
 *  - No query and no filters selected  -> show the whole collection.
 *  - Filters are real: OR within a group, AND across groups, combined with the
 *    optional text query. Dropdown options are built from the actual data.
 */
const documents = Array.isArray(window.MSF_DOCUMENTS) ? window.MSF_DOCUMENTS : [];
const pageSize = 20;
let submittedQuery = '';
let page = 0;

const LANG_LABELS = { en: 'English', fr: 'French', ar: 'Arabic', es: 'Spanish', und: 'Unknown' };

const get = (id) => document.getElementById(id);
const checked = (name) => Array.from(
  document.querySelectorAll(`input[name="${name}"]:checked`),
  (input) => input.value,
);

// Build document cards with textContent so document text cannot inject HTML.
function documentCard(record) {
  const article = document.createElement('article');
  article.className = 'card';

  const title = document.createElement('h3');
  title.dir = 'auto';
  if (record.id) {
    const link = document.createElement('a');
    link.href = `/doc/${encodeURIComponent(record.id)}`;
    link.target = '_blank';
    link.rel = 'noopener';
    link.textContent = record.title || 'Title unavailable';
    title.append(link);
  } else {
    title.textContent = record.title || 'Title unavailable';
  }

  const meta = document.createElement('p');
  meta.className = 'card-meta';
  const bits = [record.location, record.date, (record.languages || []).map((l) => LANG_LABELS[l] || l).join(', ')]
    .filter(Boolean);
  meta.textContent = bits.join(' · ');

  const excerpt = document.createElement('p');
  excerpt.dir = 'auto';
  excerpt.textContent = record.summary || 'No summary available.';

  article.append(title, meta, excerpt);
  return article;
}

// A record matches when it satisfies the query AND every active filter group.
function matchingDocuments() {
  const languages = checked('language');
  const genres = checked('genre');
  const locations = checked('location');
  const q = submittedQuery.toLocaleLowerCase();

  return documents.filter((record) => {
    const text = `${record.title || ''} ${record.summary || ''}`.toLocaleLowerCase();
    const recordLanguages = record.languages?.length ? record.languages : ['und'];
    return (!q || text.includes(q))
      && (!languages.length || languages.some((value) => recordLanguages.includes(value)))
      && (!genres.length || genres.includes(record.genre || 'unknown'))
      && (!locations.length || locations.includes(record.location || 'unknown'));
  });
}

function activeFilterCount() {
  return checked('language').length + checked('genre').length + checked('location').length;
}

function updateCounts() {
  for (const span of document.querySelectorAll('.filter-bar .count')) {
    const n = checked(span.dataset.group).length;
    span.textContent = n ? `(${n})` : '';
  }
}

function renderSearch() {
  const matches = matchingDocuments();
  updateCounts();
  get('results').replaceChildren();

  if (!documents.length) {
    get('search-status').textContent = 'No documents connected. Run `msf-retrieval export` to connect the collection.';
  } else {
    const filtered = submittedQuery || activeFilterCount();
    get('search-status').textContent = filtered
      ? `${matches.length} of ${documents.length} documents match.`
      : `Showing all ${documents.length} documents.`;
    get('results').append(...matches.slice(page * pageSize, (page + 1) * pageSize).map(documentCard));
  }

  const total = matches.length;
  get('page-status').textContent = total ? `Page ${page + 1} of ${Math.ceil(total / pageSize)}` : 'No results to display';
  get('previous').disabled = page === 0;
  get('next').disabled = (page + 1) * pageSize >= total;
}

// --- Build dropdown options from the real data -------------------------------

function filterOption(group, value, label) {
  const wrap = document.createElement('label');
  const input = document.createElement('input');
  input.type = 'checkbox';
  input.name = group;
  input.value = value;
  wrap.append(input, document.createTextNode(' ' + label));
  return wrap;
}

function distinct(selector) {
  return [...new Set(documents.flatMap(selector))].filter(Boolean).sort((a, b) => a.localeCompare(b));
}

function buildFilters() {
  const locations = distinct((r) => [r.location || 'unknown']);
  const genres = distinct((r) => [r.genre || 'unknown']);
  const languages = distinct((r) => (r.languages?.length ? r.languages : ['und']));

  get('location-filters').replaceChildren(
    ...locations.map((v) => filterOption('location', v, v === 'unknown' ? 'Unknown' : v)));
  get('genre-filters').replaceChildren(
    ...genres.map((v) => filterOption('genre', v, v === 'unknown' ? 'Unknown' : v)));
  get('language-filters').replaceChildren(
    ...languages.map((v) => filterOption('language', v, LANG_LABELS[v] || v)));
}

// --- Events ------------------------------------------------------------------

get('search-form').addEventListener('submit', (event) => {
  event.preventDefault();
  submittedQuery = get('query').value.trim();
  page = 0;
  renderSearch();
});

// Filtering applies immediately when any checkbox changes.
get('filter-bar').addEventListener('change', () => { page = 0; renderSearch(); });

get('clear-filters').addEventListener('click', () => {
  document.querySelectorAll('.filter-bar input[type="checkbox"]').forEach((i) => { i.checked = false; });
  page = 0;
  renderSearch();
});

for (const [id, step] of [['previous', -1], ['next', 1]]) {
  get(id).addEventListener('click', () => { page += step; renderSearch(); });
}

// Close any open dropdown when clicking outside the filter bar.
document.addEventListener('click', (event) => {
  if (event.target.closest('.filter-bar')) return;
  document.querySelectorAll('.filter-bar details[open]').forEach((d) => { d.open = false; });
});

// --- Documents tab: filter managed documents by title ------------------------

get('find').addEventListener('input', () => {
  const query = get('find').value.trim().toLocaleLowerCase();
  const matches = documents.filter((record) => (record.title || '').toLocaleLowerCase().includes(query));
  get('document-list').replaceChildren(...matches.map(documentCard));
  get('documents-status').textContent = !documents.length
    ? 'No documents connected.'
    : `${matches.length} documents found.`;
});

// Import tab: show the user's actual selection; do not claim files were processed.
get('files').addEventListener('change', (event) => {
  const rows = Array.from(event.target.files, (file) => {
    const row = document.createElement('li');
    row.textContent = `${file.name} · ${(file.size / 1024).toFixed(1)} KB · Not processed`;
    return row;
  });
  get('file-list').replaceChildren(...rows);
});

// --- Initial render ----------------------------------------------------------
buildFilters();
renderSearch();
